questions.codesnippet:
try:
    print("A")
    x = 1 / 0
    print("B")
except ZeroDivisionError:
    print("C")

nums = [1, 2, 3]
try:
    print(nums[5])
except IndexError:
    print("Out of range")

d = {"k": 1}
try:
    print(d["m"])
except KeyError:
    print("missing")

try:
    raise ValueError("v")
except ValueError:
    print("specific")
except Exception:
    print("generic")

try:
    d = {}
    print(d["k"])
except Exception:
    print("caught")

def f():
    try:
        return "try"
    finally:
        print("finally")
print(f())

def f():
    try:
        raise ValueError("boom")
    except ValueError:
        raise
try:
    f()
except ValueError as e:
    print(e)

try:
    x = 2 + 2
except ValueError:
    print("E")
else:
    print("OK")

try:
    try:
        raise ValueError("inner")
    except ValueError:
        print("caught inner")
    print("after inner")
except ValueError:
    print("outer")

class AppError(Exception):
    pass
try:
    raise AppError("fail")
except Exception as e:
    print(type(e).__name__, e)

def f():
    try:
        raise KeyError("k")
    finally:
        print("F")
try:
    f()
except KeyError as e:
    print(e)

def f(n):
    try:
        if n == 0:
            raise ValueError()
        print("ok")
    except ValueError:
        return "E"
    finally:
        print("F")
print(f(0))
